import { readFileSync } from "node:fs";
const src = readFileSync("src/theme.js", "utf8");
const m = src.match(/colorPrimary:\s*'([^']+)'/);
const actual = m && m[1];
const expected = "#0052d9";
console.log("token in file :", actual);
console.log("requested     :", expected);
console.log("TOKEN_MATCH   :", actual === expected);
const srgb = (c) => { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
const L = (hex) => { const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16); return 0.2126*srgb(r) + 0.7152*srgb(g) + 0.0722*srgb(b); };
const ratio = (a,b) => { const l1 = L(a), l2 = L(b); const [hi,lo] = l1 > l2 ? [l1,l2] : [l2,l1]; return (hi + 0.05) / (lo + 0.05); };
for (const bg of ["#1677ff", "#0052d9"]) {
  console.log(bg, "| white text:", ratio(bg,"#ffffff").toFixed(2), "| black text:", ratio(bg,"#000000").toFixed(2));
}
